    inputs = node_inputs("export.report", {"format": "html"})
    outputs = node_outputs("export.report")

    def update_build_config(self, build_config, field_value, field_name=None):
        return refresh_config(self, "export.report", build_config, field_value, field_name)

    def build_table(self) -> DataFrame:
        return output_table(self, "export.report")

    def build_report(self) -> Data:
        return output_report(self, "export.report")

    def build_features(self) -> DataFrame:
        return output_features(self, "export.report")

    def build_artifacts(self) -> DataFrame:
        return output_artifacts(self, "export.report")

    def build_summary(self) -> Message:
        return output_summary(self, "export.report")

